// Node.js server sketch. Start with MODEL_API_KEY set in the server environment.
import http from "node:http";

const apiKey = process.env.MODEL_API_KEY;
if (!apiKey) throw new Error("MODEL_API_KEY is not set");

const send = (res, status, body) => {
  res.writeHead(status, { "Content-Type": "application/json" });
  res.end(JSON.stringify(body));
};

http.createServer(async (req, res) => {
  if (req.method !== "POST" || req.url !== "/api/answer") return send(res, 404, { error: "not found" });
  let body = "";
  for await (const chunk of req) {
    body += chunk;
    if (body.length > 10_000) return send(res, 413, { error: "request too large" });
  }
  let question;
  try {
    ({ question } = JSON.parse(body));
  } catch {
    return send(res, 400, { error: "invalid JSON" });
  }
  if (typeof question !== "string" || !question.trim()) return send(res, 400, { error: "question is required" });
  // Authenticate the user, then call your provider's official SDK with apiKey.
  // Never include apiKey in a response or log line.
  return send(res, 501, { error: "provider call not implemented in this sketch" });
}).listen(3000, () => console.log("listening on http://localhost:3000"));

// Local framing exercise, not a provider-specific streaming client.
const bytes = new TextEncoder().encode(
  '{"text":"Hello "}\n{"text":"café"}\n{"done":true}\n'
);
const decoder = new TextDecoder();
let buffer = '';
let text = '';
let done = false;

function consume(decoded) {
  buffer += decoded;
  let newline;
  while ((newline = buffer.indexOf('\n')) >= 0) {
    const line = buffer.slice(0, newline);
    buffer = buffer.slice(newline + 1);
    if (!line.trim()) continue;
    if (done) throw new Error('Record after completion');
    const event = JSON.parse(line);
    if (event.done === true) done = true;
    else if (typeof event.text === 'string') text += event.text;
    else throw new Error('Unexpected event');
  }
}

// One-byte chunks deliberately split both records and the accented character.
for (const byte of bytes) consume(decoder.decode(new Uint8Array([byte]), { stream: true }));
consume(decoder.decode());
if (buffer.trim() || !done) throw new Error('Incomplete stream');
console.log(text);

// Fictional rates in currency units per million tokens, NOT vendor prices.
const rates = { input: 2, output: 8 };
function estimate(inputTokens, outputTokens) {
  if (![inputTokens, outputTokens].every(n => Number.isInteger(n) && n >= 0)) {
    throw new Error('Token counts must be nonnegative integers');
  }
  return (inputTokens * rates.input + outputTokens * rates.output) / 1_000_000;
}
const single = estimate(1000, 250);
console.log(`single=${single.toFixed(6)}`);
console.log(`three-attempts=${(single * 3).toFixed(6)}`);

import re

doc = {
    "id": "warranty-v2",
    "text": "Coverage lasts two years from purchase.\n\n"
            "Water damage is excluded from coverage.\n\n"
            "Returns require the original receipt.",
}


def chunk_by_paragraph(doc):
    parts = [p.strip() for p in doc["text"].split("\n\n") if p.strip()]
    return [{"source": doc["id"], "position": i, "text": p} for i, p in enumerate(parts)]


def tokens(text):
    return set(re.findall(r"[a-z0-9]+", text.lower()))


def keyword_search(chunks, query, k=2):
    terms = tokens(query)
    scored = [(len(terms & tokens(c["text"])), c) for c in chunks]
    scored = [pair for pair in scored if pair[0] > 0]
    scored.sort(key=lambda pair: pair[0], reverse=True)
    return [c for _, c in scored[:k]]


chunks = chunk_by_paragraph(doc)
for hit in keyword_search(chunks, "Is water damage covered?"):
    print(hit["source"], hit["position"], hit["text"])

def recall_at_k(relevant, ranked, k):
    relevant = set(relevant)
    if not relevant:
        return None  # Score unanswerable cases separately.
    if k < 1:
        raise ValueError('k must be positive')
    return len(relevant.intersection(ranked[:k])) / len(relevant)


value = recall_at_k(['p1', 'p2', 'p3'], ['p2', 'p8', 'p1', 'p3'], 3)
print(f'recall@3={value:.3f}')
